mermaid.chartCode:
---
config:
  sequence:
    wrap: true
    actorFontSize: 18
    messageFontSize: 18
    width: 170
    actorMargin: 40
    useMaxWidth: false
---
sequenceDiagram
 autonumber
 participant U as {{user}}
 participant P as ProxMenux
 participant R as {{registry}}
 participant X as Proxmox VE
 U->>P: {{update}}
 P->>R: {{resolve}}
 R-->>P: {{image}}
 P->>P: {{verify}}
 P->>X: {{backup}}
 P->>X: {{import}}
 P->>X: {{reapply}}
 P->>X: {{start}}
 X-->>P: {{checked}}
 alt {{healthy}}
  P->>P: {{commit}}
  P-->>U: {{updated}}
 else {{failure}}
  P->>X: {{rollback}}
  alt {{recovered}}
   P-->>U: {{restored}}
  else {{restoreFailed}}
   P-->>U: {{manual}}
  end
 end
